def sha(b):return hashlib.sha256(b).hexdigest()
def fingerprint(s):return (s.st_dev,s.st_ino,s.st_mode,s.st_nlink,s.st_uid,s.st_gid,s.st_size,s.st_mtime_ns,s.st_ctime_ns)
def directory(p):
 s=p.lstat()
 assert stat.S_ISDIR(s.st_mode) and not stat.S_ISLNK(s.st_mode) and p.resolve(strict=True)==p, str(p)
 return fingerprint(s)
def read(p,cap=FILECAP):
 a=p.lstat();assert stat.S_ISREG(a.st_mode) and a.st_nlink==1 and not stat.S_ISLNK(a.st_mode) and 0<=a.st_size<=cap,str(p)
 fd=os.open(p,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK|os.O_CLOEXEC)
 try:
  b=os.fstat(fd);assert fingerprint(a)==fingerprint(b),str(p)
  data=bytearray()
  while True:
   q=os.read(fd,min(1048576,cap+1-len(data)))
   if not q:break
   data.extend(q);assert len(data)<=cap,str(p)
  assert fingerprint(b)==fingerprint(os.fstat(fd))==fingerprint(p.lstat()) and len(data)==b.st_size,str(p)
  return bytes(data),fingerprint(b)
 finally:os.close(fd)
def create(p,b):
 assert p.parent.resolve(strict=True)==p.parent
 fd=os.open(p,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW|os.O_CLOEXEC,0o600)
 try:
  with os.fdopen(fd,"wb",closefd=False) as f:f.write(b);f.flush();os.fsync(f.fileno())
 finally:os.close(fd)
 rb,_=read(p);assert rb==b
def jbytes(x):return (json.dumps(x,sort_keys=True,indent=2,ensure_ascii=False)+"\n").encode()
def inventory(root):
 directory(root);files={};dirs={}
 for here,dn,fn in os.walk(root,followlinks=False):
  d=Path(here);dirs[str(d.relative_to(root))]=directory(d)
  dn.sort();fn.sort()
  for n in dn:directory(d/n)
  for n in fn:
   p=d/n;rel=p.relative_to(root).as_posix()
   assert not any(x in ("",".","..",".git") for x in rel.split("/")) and "\\" not in rel and not any(ord(c)<32 for c in rel)
   b,fp=read(p);files[rel]={"bytes":len(b),"sha256":sha(b),"identity":fp}
 return files,dirs
